-- Poll briefings editorial audit (owner-approved 17 Oct 2026, after the 17 Oct reassessment).
-- 24 briefings rewritten to the investigation standard (dated facts, sources, fair Yes/No
-- framing); question wording unchanged so existing votes keep their meaning. 6 polls retired
-- to the archive (duplicates, loaded wording, or a premise overtaken by events); votes kept.
-- Old text kept in public.polls_backup_20261017. Whole file rolls back if any row is missing.
\set ON_ERROR_STOP on
BEGIN;
ALTER TABLE public.polls ADD COLUMN IF NOT EXISTS explainer_sources jsonb;
ALTER TABLE public.polls ADD COLUMN IF NOT EXISTS explainer_checked date;
CREATE TABLE IF NOT EXISTS public.polls_backup_20261017 AS SELECT id, question, explainer, archived, now() AS saved_at FROM public.polls WHERE poll_type = 'yesno';
ALTER TABLE public.polls_backup_20261017 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.polls_backup_20261017 FROM anon, authenticated;
DO $do$ DECLARE n int; BEGIN
  UPDATE public.polls SET explainer = $t$England's default speed limit in built-up areas is 30mph. Wales made 20mph its default in September 2023. A Senedd petition asking for that law to be scrapped collected 469,571 signatures, and the Welsh Government has since let councils return some roads to 30mph. Vote Yes if you think lower default speeds are worth the longer journeys for the safety of pedestrians and cyclists. Vote No if you think speed limits should be set road by road, with 30mph remaining the default.$t$, explainer_sources = $t$[{"label": "Senedd petition P-06-1407 (469,571 signatures)", "url": "https://business.senedd.wales/mgIssueHistoryHome.aspx?IId=43227"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 74 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 74: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$Delivery robots already run on pavements in Milton Keynes, Cambridge, Bristol, Sheffield, Leeds and Barnsley through local trials, because no law covers them; the Highway Act 1835 bans 'carriages' from footways. Ministers are preparing a new category that would let low-speed robots use England's pavements, with councils able to set where they run, how many and to what safety standard. Starship Technologies says it hopes to sell more than 10,000 robots in England. Living Streets warns of hazards for blind and partially sighted people, wheelchair users and older pedestrians. Vote Yes if you would allow robots on pavements under rules like these. Vote No if you think pavements should be kept for people.$t$, explainer_sources = $t$[{"label": "Retail Gazette, June 2026: proposed law change", "url": "https://www.retailgazette.co.uk/blog/2026/06/delivery-robots-could-be-heading-for-englands-pavements-under-new-law-change/"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 72 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 72: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$Most PIP assessments have been held by phone or video since the pandemic; face-to-face assessments fell to 6 per cent in 2024. In December 2025 the Department for Work and Pensions said it would raise face-to-face assessments to 30 per cent from April 2026. Vote Yes if you think every assessment should be face to face, so assessors can see claimants in person. Vote No if you think remote assessments should remain an option, given that many claimants find travel difficult and assessors also have medical evidence.$t$, explainer_sources = $t$[{"label": "Benefits and Work, 29 December 2025: DWP face-to-face plans", "url": "https://www.benefitsandwork.co.uk/news/fewer-pip-reviews%2C-more-wca-reassessments%2C-more-face-to-face"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 66 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 66: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$In October 2025, 153,000 homes in England had been empty for more than a year and were charged the empty homes council tax premium; councils can charge up to 300 per cent extra on homes empty for ten years or more. Councils can already use compulsory purchase, but the process is slow and costly. Vote Yes if you think councils should get quicker powers to buy long-term empty homes and bring them back into use. Vote No if you think owners' property rights, and the cost to councils, outweigh the gain.$t$, explainer_sources = $t$[{"label": "MHCLG, Council Taxbase 2025 in England", "url": "https://www.gov.uk/government/statistics/council-taxbase-2025-in-england/local-authority-council-taxbase-in-england-2025"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 65 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 65: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$More than 200,000 people crossed the Channel in small boats between 2018 and May 2026, according to Home Office figures. Asylum claims are decided case by case. Reform UK proposes removing anyone who arrives this way without hearing an asylum claim in the UK. Vote Yes if you think automatic removal is needed to stop the crossings. Vote No if you think claims must still be heard, given the UK's obligations under the 1951 Refugee Convention and that removal needs a country willing to accept people.$t$, explainer_sources = $t$[{"label": "Home Office: migrants detected crossing the Channel in small boats", "url": "https://gov.uk/government/publications/migrants-detected-crossing-the-english-channel-in-small-boats"}, {"label": "ITV News, 9 May 2026: more than 200,000 since 2018", "url": "https://www.itv.com/news/meridian/2026-05-09/more-than-200000-migrants-have-crossed-the-channel-in-small-boats-since-2018"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 61 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 61: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$The UK helped draft the European Convention on Human Rights in 1950, and the Human Rights Act 1998 lets people rely on it in UK courts. In October 2025 the Conservative Party committed to leaving the Convention; Reform UK also supports leaving. Supporters say it limits the deportation of foreign criminals and control of immigration. Opponents say it protects everyone's rights against the state and that leaving would damage agreements that depend on it. Vote Yes if you think the UK should leave. Vote No if you think it should stay.$t$, explainer_sources = $t$[{"label": "The Scotsman, October 2025: Badenoch commits Conservatives to leaving the ECHR", "url": "https://mp.scotsman.com/uk-news/every-tory-candidate-must-back-leaving-echr-says-badenoch-5664372"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 60 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 60: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$MPs are paid a basic salary of £98,599 from April 2026. There is no minimum voting requirement and no pay penalty for missing votes. Sinn Féin's MPs do not take their seats and are not paid a salary. Vote Yes if you think voting in Parliament is a basic part of the job and long absences should cost an MP their salary. Vote No if you think MPs also work through casework, committees and campaigning, and that voting records alone should not decide pay.$t$, explainer_sources = $t$[{"label": "IPSA, 2 March 2026: MPs' pay for 2026-27", "url": "https://theipsa.org.uk/news/press-releases/ipsa-confirms-decision-on-mps-pay-for-2026-27"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 67 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 67: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$Nigel Farage received a £5 million personal gift from Christopher Harborne, Reform UK's largest donor, in 2024. Farage says he was not an MP when he received it, so there was nothing to register. The gift is under investigation by the Parliamentary Commissioner for Standards, which is an investigation, not a finding. Vote Yes if you think a gift of this size from a party donor should be declared whatever its timing. Vote No if you think gifts received before becoming an MP fall outside the Commons rules.$t$, explainer_sources = $t$[{"label": "Open Govt investigation: Christopher Harborne's funding of British politics", "url": "/editorials/p4w9k2xr7n"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 70 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 70: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$At the 2024 general election Labour won 411 of 650 seats on 33.7 per cent of the vote, the Liberal Democrats 72 seats on 12.2 per cent, and Reform UK 5 seats on 14.3 per cent. The Liberal Democrats, Greens and Reform UK support proportional representation; Labour and the Conservatives do not. Vote Yes if you think seats should match votes more closely. Vote No if you think single-party government and the link between one MP and one constituency matter more.$t$, explainer_sources = $t$[{"label": "Full Fact: the 2024 general election in numbers", "url": "https://fullfact.org/election-2024/general-election-result-numbers/"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 68 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 68: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$The government has pledged 1.5 million new homes in England in this Parliament. One proposal is a public developer that builds directly on public land, as the post-war new town development corporations did. Vote Yes if you think the state should build homes itself to make up the shortfall. Vote No if you think a public developer would compete with private builders for the same workers and materials, and that planning and skills are the real limits.$t$, explainer_sources = $t$[]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 64 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 64: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$Capital gains tax on most assets is charged at 18 per cent for basic-rate taxpayers and 24 per cent for higher-rate taxpayers. Income tax in England is charged at 20, 40 and 45 per cent. Vote Yes if you think income from selling assets should be taxed at the same rates as income from work. Vote No if you think higher capital gains tax would deter investment and lead people to hold assets longer, so it might raise less than expected.$t$, explainer_sources = $t$[]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 62 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 62: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$Labour's 2024 manifesto said it would not increase National Insurance. In October 2024 the government raised employer National Insurance from 13.8 to 15 per cent and lowered the threshold at which employers pay from £9,100 to £5,000. The government says the pledge covered taxes paid by working people. The OBR estimates that 76 per cent of the cost will eventually fall on workers through lower real wages. Vote Yes if you think this broke the manifesto. Vote No if you think the pledge covered only the National Insurance employees pay.$t$, explainer_sources = $t$[{"label": "Open Govt investigation: the National Insurance pledge", "url": "/editorials/whr8acs2gf"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 63 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 63: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$MPs are paid a basic salary of £98,599 from April 2026 and may hold other paid jobs if they declare them in the Register of Members' Financial Interests. Paid lobbying of ministers on behalf of an employer is banned. Vote Yes if you think outside work keeps MPs connected to the wider economy and brings expertise into Parliament. Vote No if you think being an MP should be a full-time job, and outside interests risk conflicts.$t$, explainer_sources = $t$[{"label": "IPSA, 2 March 2026: MPs' pay for 2026-27", "url": "https://theipsa.org.uk/news/press-releases/ipsa-confirms-decision-on-mps-pay-for-2026-27"}, {"label": "Open Govt: second jobs and outside earnings", "url": "/second-jobs"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 69 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 69: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$Storm overflows in England spilled sewage 291,492 times in 2025, 35 per cent fewer than in 2024, according to the Environment Agency, which credits drier weather in part. Water companies in England are privately owned and regulated by Ofwat and the Environment Agency. Vote Yes if you think public ownership is needed to stop sewage spills. Vote No if you think stronger regulation and enforcement can do it without the cost of buying the companies.$t$, explainer_sources = $t$[{"label": "Environment Agency, 26 March 2026: storm overflow spills in 2025", "url": "https://www.gov.uk/government/news/fewer-and-shorter-storm-overflow-spills-in-2025-new-monitoring-data-shows"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 58 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 58: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$Food price inflation reached 19.2 per cent in March 2023, the highest in more than 40 years. It had fallen to 1.7 per cent by June 2026, according to the ONS. Vote Yes if you think a temporary cap on basic foods would protect households when prices rise quickly. Vote No if you think price caps lead to shortages and are better replaced by targeted help for low-income households.$t$, explainer_sources = $t$[{"label": "Express & Star, July 2026: ONS food inflation", "url": "https://www.expressandstar.com/uk-news/food-inflation-hits-lowest-rate-in-almost-two-years-but-set-to-rise-again-8815719"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 53 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 53: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$The government has committed to raise defence spending to 2.5 per cent of national income by 2027. Health and welfare are much larger budgets. Within a fixed total, more for one means less for others, higher taxes or more borrowing. Vote Yes if you would protect health and welfare spending even if defence gets less. Vote No if you think defence should be protected first.$t$, explainer_sources = $t$[]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 59 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 59: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$From 1 April 2026 the government ended the Energy Company Obligation and moved 75 per cent of the Renewables Obligation's cost into general taxation, cutting about £150 from a typical household's yearly bill. Other policy costs remain on bills. Vote Yes if you think the remaining levies should also come off bills while prices are high. Vote No if you think they should stay to fund renewable energy and efficiency schemes.$t$, explainer_sources = $t$[{"label": "DESNZ, 27 November 2025: what the Budget means for energy bills", "url": "https://www.gov.uk/government/news/what-does-the-autumn-budget-mean-for-your-energy-bills"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 56 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 56: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$The UK left the EU Single Market on 1 January 2021, when the Brexit transition period ended. Trade with the EU now runs under the Trade and Cooperation Agreement, with customs checks on goods. Rejoining the Single Market would mean accepting free movement of people and EU rules without a vote on them. Vote Yes if you would hold a referendum on rejoining. Vote No if you would not.$t$, explainer_sources = $t$[]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 46 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 46: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$Labour's 2024 manifesto pledged not to issue licences to explore new oil and gas fields. The last licence was offered in May 2024, and in November 2025 the government confirmed it would not issue new exploration licences; existing fields keep producing. Vote Yes if you think new licences would help energy bills and supply. Vote No if you think they would make little difference to prices, which are set by world markets, and would conflict with climate targets.$t$, explainer_sources = $t$[{"label": "Full Fact government tracker: new oil and gas licences", "url": "https://fullfact.org/government-tracker/new-oil-gas-field-licences/"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 42 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 42: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$Net migration to the UK peaked at 944,000 in the year to March 2023 and was 171,000 in the year to December 2025, according to the ONS. Governments set targets but no law caps the number. Vote Yes if you think a legal cap would make governments keep their promises. Vote No if you think a fixed cap would stop employers recruiting the workers they need.$t$, explainer_sources = $t$[{"label": "Full Fact: net migration to the UK", "url": "https://fullfact.org/immigration/net-migration-to-the-uk"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 45 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 45: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$Police can already impose conditions on, or stop, protests that cause serious disruption, under the Public Order Act 1986 as amended in 2022 and 2023. Slow marches on roads have been a recurring tactic since 2022. Vote Yes if you think police need wider powers to stop protests that block traffic. Vote No if you think existing powers are enough and wider ones would restrict the right to protest.$t$, explainer_sources = $t$[]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 41 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 41: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$The Commons decides MPs' suspensions by vote, on the recommendation of the Committee on Standards; there is no automatic ban for misleading the House. A suspension of at least 10 sitting days (or 14 calendar days) triggers a recall petition in the MP's constituency under the Recall of MPs Act 2015. Vote Yes if you think MPs found to have knowingly lied should be banned for life. Vote No if you think the existing suspension and recall system is the right response.$t$, explainer_sources = $t$[{"label": "Recall of MPs Act 2015", "url": "https://www.legislation.gov.uk/ukpga/2015/25/crossheading/how-an-mp-becomes-subject-to-a-recall-petition-process/enacted/data.htm"}]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 44 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 44: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$By convention, Westminster does not normally legislate on devolved matters without the consent of the Scottish Parliament or the Senedd. The Supreme Court ruled in 2017 that this convention is not legally enforceable. Vote Yes if you think Scotland and Wales should have a legal power to block Westminster laws on devolved matters. Vote No if you think Parliament should remain sovereign across the UK.$t$, explainer_sources = $t$[]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 49 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 49: % rows', n; END IF;
  UPDATE public.polls SET explainer = $t$UK laws pass through Parliament without public votes, whatever their cost; national referendums are rare and ad hoc. In Switzerland, citizens can force a national vote on a new law with 50,000 signatures, and many cantons hold compulsory votes on large spending decisions. Vote Yes if you think any law costing more than £10 billion should go to a public vote first. Vote No if you think MPs are elected to make these decisions.$t$, explainer_sources = $t$[]$t$::jsonb, explainer_checked = DATE '2026-10-17' WHERE id = 52 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'poll 52: % rows', n; END IF;
  UPDATE public.polls SET archived = true WHERE id = 43 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'retire 43: % rows', n; END IF;
  UPDATE public.polls SET archived = true WHERE id = 47 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'retire 47: % rows', n; END IF;
  UPDATE public.polls SET archived = true WHERE id = 48 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'retire 48: % rows', n; END IF;
  UPDATE public.polls SET archived = true WHERE id = 50 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'retire 50: % rows', n; END IF;
  UPDATE public.polls SET archived = true WHERE id = 51 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'retire 51: % rows', n; END IF;
  UPDATE public.polls SET archived = true WHERE id = 71 AND poll_type = 'yesno' AND archived = false;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1 THEN RAISE EXCEPTION 'retire 71: % rows', n; END IF;
END $do$;
SELECT archived, count(*) AS polls, count(explainer_checked) AS checked FROM public.polls WHERE poll_type = 'yesno' GROUP BY 1;
COMMIT;
